test("preprocess narrows input from annotated argument", () => {
  const pre = z.preprocess((v: string) => v.length, z.number());
  expectTypeOf<z.input<typeof pre>>().toEqualTypeOf<string>();
  expectTypeOf<z.output<typeof pre>>().toEqualTypeOf<number>();
  const obj = z.object({ a: z.preprocess((v: string | number) => String(v), z.string()) });
  expectTypeOf<z.input<typeof obj>>().toEqualTypeOf<{ a: string | number }>();
  const a: z.ZodPreprocess<z.ZodNumber> = pre;
  const b: z.core.$ZodPreprocess = pre;
  expect([a, b]).toHaveLength(2);
});
